quests[42268] = { id = 42268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwrecked Sailors", description = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.>\n\n<The sailors are being treated very poorly. It looks like a rescue operation is in order.>", objectives = "Rescue 10 Queen's Reprisal Sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
