quests[42271] = { id = 42271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Dying Breaths", description = "I have precious little time. As we speak, my troops are defending against an onslaught of withered elves.\n\nThese four whelplings are near death. Their lives are of the utmost importance to our flight, as they may be some of the last whelplings Senegos can rear.\n\nSome cracked ley crystals should bring them back to their senses.", progress = "Oh no...", completion = "Of course they would attack now.\n\nThose withered devils couldn't have chosen a more effective time to strike. My brood already suffers.", objectives = "Obtain 4 Cracked Ley Crystals, then use them to resuscitate the Mana-Drained Whelplings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
