quests[42365] = { id = 42365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Focusing the Energies", description = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln.\n\nThis rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", progress = "Were you able to find the Blood of Sargeras?", completion = "Excellent, Archdruid. These will do nicely.", objectives = "Collect 3 Blood of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42366] = { id = 42366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bigger They Are, The Harder They Fel", description = "I have had it with these small fry, assistant. Time to go straight to the top.\n\nThe tome is the key! The key to unlocking the potential within our people.\n\nDo not worry, young one. I have enough power to complete the task at hand. Let us harness fel magic and change the future.\n\nFollow me and witness the redemption of the shal'dorei!", completion = "Kyrtos, you old fool! You should have known the risks...", objectives = "Assist Kyrtos with his ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42367] = { id = 42367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkethrax", description = "Within the Ingress is a demon who must die.\n\nArkethrax is a creature of cunning evil. If left unchecked he will be able to use the Ingress as a staging point for targeted assaults that will decimate our forces.\n\nI, for one, have no intention of underestimating this opponent and shall join you on the battlefield when you are ready to fight him.", completion = "With Arkethrax and his minions dealt with it should help prevent them from flanking Illidari Stand. Well done.", objectives = "Slay Arkethrax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42368] = { id = 42368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quantity Over Quality", description = "The demons of Felblaze Ingress are amassing at an exponential rate.\n\nWe must cull these invaders before they have enough demons to flank our forces at Illidari Stand.\n\nWill you join us in battle?", completion = "That should stall these demons for a time. We may need to return in the future to ensure they have not regrouped.", objectives = "Slay demons in the Felblaze Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42369] = { id = 42369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Doing it Wrong", description = "These demon portals are terrible and sloppy. No skill or finesse in it.\n\nThis physically hurts me and I haven't felt real pain in decades.\n\nI \"fixed\" some of the Legion's precious Portal Stabilizer crystals.\n\nI want you to take them and \"modify\" their main portal in the Ingress and watch the \"hilarity\" ensue.", progress = "Did you see the look on those demons' faces? Priceless!", completion = "If you think the explosion was big on our side of the portal, you should see what the other side looks like. Ha!", objectives = "Place 4 Sabotaged Portal Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42370] = { id = 42370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanding 101", description = "We'll start with some wand work. You have your wand with you? Good.\n\nI've set up a number of targets around the hall. Use your wand to hit as many as you can.\n\nAnd no point-blank shots! That's cheating.", progress = "You'll never learn if you never practice.", completion = "And... it looks like we're out of time for today's wand practice. Go on, then. Off to your next class!", objectives = "Practice using your wand on 10 Wand Targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42371] = { id = 42371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Study Hall: Combat Research", description = "What's this? A new, confused student, desperately trying to win the favor of the headmistress, wandering the halls without anything to do?\n\nPerfect! I need help with my research.\n\nI'm writing a paper on combat. Grab me some books from the shelf over there.", progress = "I agree. Research can be grueling work.", completion = "My hand is beginning to tire from taking so many notes. I think it's time we took a break.", objectives = "Obtain the books that Sythorne requests, then help him defeat the challenges within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42372] = { id = 42372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felblaze Ingress", description = "It is my mission to cover the rear guard of Illidari Stand. I have employed this warlock... thing, to assist me.\n\nHowever, the two of us are insufficient for a task that needs doing.\n\nTo the east is a mass of demons at Felblaze Ingress. These creatures have begun to open portals to summon in countless reinforcements.\n\nMeet us at Felblaze Ingress and together we can crush this fel insurgency.", completion = "Keep your voice down unless you feel like being felbat food.", objectives = "Meet Tehd Shoemaker at Felblaze Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42373] = { id = 42373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for the Stonedark" }
quests[42374] = { id = 42374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Greeting Kits - Tracking Quest" }
quests[42375] = { id = 42375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye See You", description = "There is being blind, and then there is being stupid.\n\nThis eyeless wonder next to me wants to barrel into Felblaze Ingress without preparation.\n\nBah! I say we scout it first.\n\nHere, I will provide you with an extra eye I picked up from a place better left unmentioned.\n\nEnter Felblaze Ingress, investigate the area, and try not to get poked in the eye.", progress = "Don't ask where I got the eye. Worst case is I tell you and then it gets all awkward between us.", completion = "Why? Why would demons, of all things, be this bad at summoning their own kind?", objectives = "Use Tehd's Eye of Kilrogg to investigate Felblaze Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42376] = { id = 42376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Tivos" }
quests[42377] = { id = 42377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brother's Trail", description = "We must reclaim the Silver Hand before those with evil intent can seize it. To free it from its wards, we need relics called the Sparks of Tyr. I have one, as does my brother, Galford.\n\nHe journeyed to Northrend to seek aid from the Tyr's homeland, but has not returned.\n\nI must ask you to find him, and his Spark.", progress = "Any news on my brother? Or the Spark of Tyr?", completion = "A terrible loss. You have the Spark he held, though, and I have another.\n\nWe must press on. I will mourn Galford another day.", objectives = "Go to Dragonblight in Northrend and find Galford and his Spark of Tyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42379] = { id = 42379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Power", description = "It appears you & your weapon are both growing in strength. Return to me at the Heart of Azeroth. I have more to show you.", objectives = "Use the Ancient Elemental Altar to imbue your artifact, then speak to Advisor Sevel at the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42381] = { id = 42381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ox'iloth" }
quests[42383] = { id = 42383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", description = "The Earthen Ring is built upon the strength and dedication of its members.\n\nIf we are to help defend this world against the Burning Legion, we will need to grow our order, and recruit skilled champions to our side.\n\nBegin by speaking to Stormcaller Mylra and Duke Hydraxis. Perhaps they would be willing to fight for us.", completion = "Excellent. Stormcaller Mylra and Duke Hydraxis are worthy champions. We can trust them to carry out any task we ask of them.", objectives = "Recruit Stormcaller Mylra and Duke Hydraxis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42384] = { id = 42384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Reports", description = "In the recent past, our order has spent a lot of time watching and waiting. With you at the helm, we'll be able to focus on our original calling.\n\nTake a look around us, {name}. Azeroth needs us now more than ever. The same enemy that led to our formation is threatening us once again.\n\nYou should send someone to gather reports from our scouts. From there, we'll be able to focus our efforts where they are needed most.", completion = "I've received word from our scouts, and just in time it seems. There are plenty of people out there who could use our help.", objectives = "Interact with the Scouting Map and complete \"Scouting Reports\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42385] = { id = 42385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lending a Hand", description = "Our scouts reported seeing a village in Val'sharah being attacked by undead hounds.\n\nThis is the perfect opportunity for the Unseen Path to make good on our promise to help those in need.\n\nYou should head out to Bradensbrook and see what you can do to help.", completion = "I don't know who sent you, but I sure hope you're here to help.", objectives = "Find Hudson Crawford in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42386] = { id = 42386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rising Troubles", description = "Our village is swarming with beasts risen from the dead!\n\nThe abominations never rest! They attack night and day.\n\nWe're doing our best to keep them at bay, but it's getting to be more than the townsfolk can handle. They're tired and losing their will to fight.\n\nAnything you can do to lessen the burden would be greatly appreciated.", progress = "We'll keep fighting as long as the hounds keep coming. Bradensbrook will not be lost to those beasts!", completion = "Whatever you did out there, it worked. The hounds' attacks have slowed.\n\nLet's hope that the villagers can get some rest, and live to fight another day.", objectives = "Kill Risen Hounds in and around Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42387] = { id = 42387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassin Entrapment", description = "Black Rook invaders are still targeting our farms and homes, even though there's not much left to pillage.\n\nWe had hoped that once they cleared us out that the attacks would stop, but it seems those mindless ghouls will follow any orders given by their commander.\n\nWe'd take him out ourselves, but he's a sneaky fella. The only way we're going to catch him, is if someone lays a trap. I can provide the supplies if you're willing to help.", completion = "Thank you, {name}. I think the children will be able to sleep better tonight knowing that those assassins aren't lurking just outside their door.", objectives = "Set a trap at Carlisle Cottage to catch and kill Captain Tevaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42388] = { id = 42388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Summons", description = "The eagle appears to have a message for you:\n\n\n\nOur scouts have returned with reports from all over Azeroth. It seems that things are much worse than they initially seemed.\n\nReturn to Trueshot Lodge as soon as you can.\n\n-Emmarel Shadewarden", completion = "I'm so glad we're able to help people once again. Your work in Bradensbrook just proves how much the Unseen Path is needed.\n\nSince you've been away, we've had reports pouring in from all over Azeroth. With our ranks a little low, I'm not sure we'll be able to keep up.", objectives = "Speak to Emmarel Shadewarden at Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42389] = { id = 42389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling Hilaire Home", description = "With so many in need of our help, it may be time to call in some of our scouts in the field.\n\nOne such scout is a huntress by the name of Hilaire. Although she abandoned her clan long ago to join our order, she still feels a need to watch over them.\n\nHer dedication to protect those who would shun her is admirable, but we need her here.\n\nSeek Hilaire out in Stormheim, and let her know it's time to come home.", progress = "Have you found Hilaire yet? She's a dedicated huntress, one who's more than willing to protect those who cannot protect themselves.", completion = "It's been quite some time since I've come across another from our order.\n\nIf you've come to collect me, I'm afraid that's not going to happen.", objectives = "Find Beastmaster Hilaire in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42390] = { id = 42390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting Rexxar", description = "To do the most good, we need the best hunters at our side.\n\nHaving you leading the order is a great start, but we'll need others who share your skill and expertise if we plan on making an impact.\n\nRexxar has a reputation of being one of the greatest hunters of his time, yet he's never been eager to aid the Unseen Path.\n\nHe has a camp just north of here, where he and Misha live off the land. Maybe you can convince him to join our ranks.", completion = "You're from the lodge on the hill, am I right? I've heard of your order, a respectable group no doubt, but a bit dull for my tastes.", objectives = "Find Rexxar in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42391] = { id = 42391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bite of the Beast", description = "I will not leave my post without Cora.\n\nA group of mages have her caged up like a beast, threatening to put her down.\n\nThey claim she's responsible for the death of one of their own, but I refuse to believe that. Cora is a loyal and obedient companion; she would never attack without my command.\n\nI tracked the demon that was truly responsible to this location, but it put up quite a fight before getting away. My injuries prevented me from giving chase, but I am sure that beast has left a bloody trail.", progress = "I will not go anywhere until Cora is at my side.", completion = "Thank you for securing Cora's release. She's still a bit skittish, but I think she'll recover in time.", objectives = "Find the beast responsible for the attacks and bring its head to the mages holding Cora captive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42392] = { id = 42392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survive the Night", description = "Now it's time to put your skills to the test.\n\nYour order seems to be a lot of watching and waiting without a lot of action.\n\nProve me wrong. Show me that I might have something in common with the Unseen Path.\n\nIf you survive a night in the wild, then I will consider joining your order.", progress = "You need to eat to survive in the wild.\n\nBoar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however.\n\nThere are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often determine which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat.\n\nThe best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.", completion = "Well, you've got my attention, {name}. Not many hunters have what it takes to survive a night in these unforgiving mountains.", objectives = "Survive a night within Cliff's Edge according to Rexxar's rules.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42393] = { id = 42393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homecoming", description = "Cora has calmed enough to make the journey back to Trueshot Lodge.\n\nYou can let Emmarel know that we are on our way home.", completion = "It is so good to have Hilaire back at the lodge. Her dedication and skill will be useful in the times to come.", objectives = "Return to Emmarel Shadewarden at Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42394] = { id = 42394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseen Protection", description = "We will not let the city of Dalaran fall.\n\nIf the Legion is planning an attack, the Unseen Path will be there to stop it.\n\nOur scouts' most recent reports list a few other areas that sound like they could really use our help, whether they realize it or not.\n\nAs soon as you're able, send your hunters to take care of the threats.", completion = "Whether they know it or not, the people of Azeroth have the Unseen Path to thank for their safety.", objectives = "Use the Scouting Map to send your champions and troops on \"Unseen Protection\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42395] = { id = 42395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signaling Trouble", description = "Long ago, we gave select leaders special flares that were only to be used in times of great need.\n\nUpon seeing the flare, the leader of the Unseen Path is supposed to head to the southern watchtower to meet with whomever lit it.\n\nI don't know who we'll face once we reach the tower, but we must move quickly.", completion = "I fear that the Burning Legion is planning to invade Dalaran.\n\nI've dispatched members of the Kirin Tor to spy on various demon strongholds, with hopes that they can uncover any plots involving the city.\n\nIn the meantime, Dalaran could benefit from the protection of the Unseen Path. I know its citizens will be safe with the Unseen Path watching over them.", objectives = "Meet Emmarel at the top of the southern watch tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42396] = { id = 42396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do The Thing!", description = "Mrglrg! Mrlglr mrgllrg.\n\n<Phin gesticulates wildly>\n\nMrlgrlg glrglmglr mrlglrg. Rglrgmrg mrglr glr. Glr! Gmrlgrmlg mrglmrgm...\n\n<Phin looks at you expectantly.>", progress = "Mrlgr?", completion = "<Phin grabs your shoulders and hops happily.>\n\nMlrglr! Grlrlrglrmg.", objectives = "?????", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42397] = { id = 42397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron and the Huntsman", description = "We've received word from Khadgar that he's lost contact with the mages he sent to investigate the Legion's camps. He's requested our assistance in tracking them down.\n\nIf we have any hope of locating those mages, we'll need to find ourselves a reliable hound capable of following a scent.\n\nThere is only one such hound that I know of, and he's long since retired. It's worth it to check in with his master, Hunstman Blake, and see if old Baron still has it in him.", completion = "You traveled all this way to see Baron? It's been a long time since we've had visitors.", objectives = "Find Huntsman Blake in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42398] = { id = 42398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening the Senses", description = "I'm afraid old Baron here is past his prime. His nose can't catch a scent the way it used to. Others told me to put him down, but I can't bear the thought of losing my loyal friend.\n\nBaron was always at his best when working, though. Maybe if you let him wander through these fields and dig up some old bones, it'll be enough to awaken his senses.", progress = "How's old Baron holding up?", completion = "I don't know what kind of bones you and Baron found in these fields, but he hasn't had this much energy since he was a pup!", objectives = "Help Baron awaken his senses by digging up Ancient Bones within the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42399] = { id = 42399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to Work", description = "If Baron's ready to work, I am too.\n\nWe'll make our way to the hunter's lodge as soon as I pack up camp and get this dog fed. I'm sure with all that digging, he'll have a hearty appetite.", completion = "Good work recruiting Huntsman Blake. His hound could be the key to tracking down Khadgar's mages.", objectives = "Return to Emmarel Shadewarden in Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42400] = { id = 42400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Mages", description = "The Archmage has already made his way to Suramar, where the missing mages were last seen.\n\nBaron ran off, too. It seems that hound is eager to work again.\n\nMeet them both near the road that leads into the city. With any luck, Baron will be about to pick up on their magical scent and find the missing mages before it's too late.", completion = "Thank you for meeting me, {name}.", objectives = "Meet Archmage Khadgar in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42401] = { id = 42401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Magic", description = "This is the last known location of the missing Kirin Tor. There isn't much evidence, other than a torn piece of cloth, which looks to be from one of our tabards.\n\nThe scrap may be small, but it should be heavy with the essence of magic. We can only hope that Baron can catch the scent and track down the mages.", completion = "The Houndmaster is an ancient and powerful demon who has attacked our world once before.\n\nHis return could have dire consequences for mages throughout Azeroth.", objectives = "Follow Baron as he tracks the scent of the mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42402] = { id = 42402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requesting Reinforcements", description = "Many powerful factions have pledged their loyalty to the Unseen Path. It's time that we call on them to help us defeat Hakkar and his demon hounds.\n\nSend your champions into the field to track down these leaders and let them know we require their help.", completion = "Our allies have all gathered here at the lodge and are waiting to be updated on the situation.", objectives = "Interact with the Scouting Map and complete the mission \"Requesting Reinforcements\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42403] = { id = 42403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmountain Hunters", description = "I've just received word from our scouts that they've identified some potential recruits.\n\nIt seems as though the famed Hemet Nesingwary has set up camp not too far from our lodge.\n\nWhile he isn't traditionally the type of hunter we'd invite into our ranks, his experience hunting large game could come in handy.\n\nHead on over to his retreat and see if he's willing to aid our cause.", completion = "You're from the lodge up on the hill, aren't ya?", objectives = "Find Hemet Nesingwary in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42404] = { id = 42404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting the Archmage", description = "Hakkar maintains an army of felhounds that feed off of magic. As long as he remains within Azeroth, no mage will be safe.\n\nHe and his hounds are immune to most spells, so I must ask for assistance in killing them.\n\nYou have proven yourself more than capable, but are you willing to help take down this demon?", completion = "If we can help, we should help. Hakkar isn't welcome in our world, and he won't be allowed to stay.", objectives = "Return to Emmarel Shadewarden at Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42405] = { id = 42405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing Our Allies", description = "Leaders from some of the greatest military factions are here, ready and willing to help.\n\nThey're currently waiting to speak with you directly, hoping to provide insight on how they can help.\n\nWith any luck, we can pull our resources and find a way to take Hakkar down.", progress = "We cannot hope to defeat Hakkar without the help of our allies.", completion = "With the faction leader's help and your leadership, Hakkar doesn't stand a chance.", objectives = "Speak to Archmage Khadgar, Halduron Brightwing, Vereesa Windrunner, and Shandris Feathermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42406] = { id = 42406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tame the Beast", description = "Deep in the heart of Faronaar are dens that are overrun with felhounds. If Hakkar is breeding those beasts, that is the place he would do it.\n\nThe bait I've crafted is potent. Once you apply it, you'll draw the attention of nearby hounds, so only use it when you're close to the dens.\n\nOnce the demon has taken the bait, get it into a weakened state to make trapping easier.\n\nGood luck, {name}. I hope you return in one piece.", progress = "Be careful not to kill the felhound when trapping it. I need the subject alive to perform my tests.", completion = "The Houndmaster has done some interesting things with this breed of felhound.", objectives = "Use the Leyworm Bait while in Felbeast Dens to lure and trap a felhound fledgling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42407] = { id = 42407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nature of the Beast", description = "By nature, this demon is immune to magic, but it has also been bred to be resistant to physical attacks. It's covered in scales unlike anything I've ever seen; layered and thick. I doubt that most metals will be able to pierce the demon's armor-like hide.\n\nUnless your entire army has weapons like yours, I suggest fighting those beasts with something that will exploit their weakness.", completion = "This is unsettling news. If our weapons won't work against Hakkar's minions, how are we going to defeat him?\n\nWe should call in our allies and see what they can do to help.", objectives = "Return to Emmarel Shadewarden at Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42408] = { id = 42408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Required Reagents", description = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons.\n\nShe provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", progress = "The enchanting process cannot be completed without the proper reagents.", completion = "This should do.", objectives = "Collect the required crafting reagents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42409] = { id = 42409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Loren Stormhoof", objectives = "I've been expecting you, {name}. Ohn'ahra's presence told me that change would be coming.\n\nThe Highmountain tribes have long been allies of the Unseen Path.\n\nMy ancestors welcomed Namuria and her hunters to our land, and together, they helped build the lodge you stand in today.\n\nI am honored to serve at your side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42410] = { id = 42410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rexxar", objectives = "An old threat has resurfaced, stronger than ever. Azeroth needs hunters like you who are willing to survive at all costs.\n\nAs the leader of the Unseen Path, many will look to you for guidance. Show them that they can survive.\n\nI will stand beside you, and together we will send a message that we can endure, even in the face of an enemy as great as the Burning Legion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42411] = { id = 42411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Beastmaster Hilaire", objectives = "I knew it was only a matter of time before us scouts would be called home.\n\nMy post has been a quiet one over the years, without much to act on. Yet in recent times, I've seen the clans abandon their traditions in favor of following a king who chose to side with the Legion.\n\nThe people I sought to protect, allied with my enemy. I will not let others find a similar fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42412] = { id = 42412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Huntsman Blake", objectives = "You brought a tear to this old man's eye by bringing Baron back to life. I never thought I'd miss his ear-piercing howls, but I did. It's a wonderful thing to see him working again.\n\nWe're happy to help wherever we're needed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42413] = { id = 42413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hemet Nesingwary", objectives = "Ya did a fine job takin' down that bird.\n\nMaybe I was wrong about you hunters up in that lodge. Clearly ya know what you're doin'.\n\nI'd be happy to hunt by your side again, as long as you're huntin' big game!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42414] = { id = 42414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Addie Fizzlebog", objectives = "I don't think Hemet himself could have taught me better, but I have to believe there's more to hunting than taking down big game.\n\nSticking with you, I think I'll be able to learn exactly what it means to be a true {class}.\n\nHere's to you, and the many grand adventures that await us!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42415] = { id = 42415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Halduron Brightwing", objectives = "You faced Hakkar with more strength and courage than I have seen in quite some time.\n\nAs Emmarel said, our battle with the Legion has only just begun. You can count on the Farstriders to be there when you need us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42416] = { id = 42416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Council is in Session", description = "Archmage Vargoth's involvement with the Empyrean Society is troubling. However, as he has proven his loyalty to the Kirin Tor many times, we must give him the benefit of the doubt for now. \n\nStill, I am obligated to share our concerns with the rest of the Council. You had best travel to Dalaran and meet with them in the Violet Citadel. I will remain here to care for our old friend.", completion = "If it is true that Archmage Vargoth is exploring fel magic, I will be shocked! Still, we owe you our thanks in bringing this matter to our attention.", objectives = "Speak to the Council of Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42417] = { id = 42417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilebrain" }
quests[42418] = { id = 42418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Visitor", description = "Archmage Vargoth's long-time apprentice, Ravandwyr, has arrived here in the Hall of the Guardian with an urgent message from his mentor.\n\nHe will be waiting for you upstairs. You had best find him quickly, {name}!", completion = "Have we met before? Your face seems a bit familiar.", objectives = "Meet up with Ravandwyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42420] = { id = 42420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Farondis", description = "Assist the Court of Farondis in Azsuna by completing 4 world quests.", completion = "The Court of Farondis thanks you.", objectives = "Complete any 4 world quests in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42421] = { id = 42421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightfallen", description = "Assist the Nightfallen of Suramar by completing 4 world quests.", progress = "Assist us, and we will reward you.", completion = "The nightfallen thank you.", objectives = "Complete any 4 world quests in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42422] = { id = 42422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wardens", description = "Assist the Wardens by completing 4 world quests.", completion = "The wardens thank you.", objectives = "Complete 4 Wardens world quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42423] = { id = 42423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Vargoth's Retreat", description = "Archmage Vargoth has been absent for a while. You may have a look around his living quarters here in the citadel tower, {name}. Kalec will escort you there.\n\nI will hold out hope that our esteemed colleague is merely up to his usual eccentricities.", progress = "What have you discovered, {name}?", completion = "Hmm. This appears to be Archmage Vargoth's notes on the Nightborne Soulstone. Supposedly the energy of captured souls stored within it can be channeled directly from the stone! If that's true, it is very powerful, indeed!", objectives = "Investigate Archmage Vargoth's quarters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42424] = { id = 42424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following In His Footsteps", description = "Archmage Vargoth seems to be mixed up in something dangerous, not that that's unusual for an archmage of his caliber and experience!\n\nThe Arcway Vaults may be where he's headed, but we should investigate all leads in order to get a better idea of what he's up to.", progress = "Have your champions discovered anything of note about Archmage Vargoth?", completion = "Good news! Your champion found Archmage Vargoth entering the Arcway Vaults in Suramar.", objectives = "Ask your champions to investigate Archmage Vargoth's travels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42425] = { id = 42425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Down, Going Up", description = "Now that we have the necessary worm guts, I was able to fashion them into a special sort of rope.\n\nIt will allow you to descend from the bridge into the chasm below and recover some of my possessions that were stolen and thrown in by the Deeprock.", progress = "I have never been particularly fond of heights.", completion = "I can't believe it! I hoped it would work, but I couldn't be sure.\n\nYou recovered heirlooms passed down by my family for many generations.\n\nI thought them lost forever.", objectives = "Use Oren's Rappel Point to descend into the depths and recover his lost possessions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42426] = { id = 42426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Test Enabled" }
quests[42427] = { id = 42427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42428] = { id = 42428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Ashamane", description = "The mighty Ancient, Ashamane, fell in battle against the Burning Legion ten thousand years ago. To honor her sacrifice, a group of devoted druids called the Ashen forged Ashamane's fangs into powerful daggers.\n\nTake my signet and present it to their leader, Delandros Shimmermoon. He will know that you have my blessing.\n\nOur flight master, Danise Stargazer, can see you to the shrine.", completion = "Rensar sent you? As much as I'd like to help, whatever you need is going to have to wait. As you can see, we have bigger problems.\n\nActually, we could really use your help. If you could lend us your aid then I'll do all that I can to help you with whatever it is you're here for.\n\nWould this be acceptable?", objectives = "Speak to Danise Stargazer and travel to Ashamane's Fall in search of Delandros Shimmermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42429] = { id = 42429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Ebonchill", description = "Is that Ebonchill you've got there? Alodi's old staff? My my my... <Cough>\n\nIn the days of the first guardian, all the members of the Council of Tirisfal granted their powers to the young mage in the hopes that he could overcome the Legion. <Wheeze> None of them are alive today... but that staff of yours remembers.\n\nSearch the streets of Dalaran below for reflections of the former council members. Their memories may empower you as they once did Alodi. Seek them out and speak with one!", progress = "Seek out the memories of the former Council members. None are here in the upper floors of the tower, and none would be in the sewers. <Cough> Check the public squares, the inns, the lower floors of the tower, the streets... A sharp eye is your ally.", completion = "Ah, your eyes gleam with newfound knowledge, {name}.\n\nThat staff of yours has seen the passing of many mortal lifetimes.  It can teach you a great many things, if you're willing to listen.\n\nAs for its memories... they may be unreliable. You may find a different reflection haunts the streets of Dalaran each day. I leave it to you to find them all.", objectives = "Find a Reflection of the Council of Tirisfal in Dalaran City. Speak with one to receive his or her wisdom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42430] = { id = 42430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fangs of Ashamane", description = "I have to admit, Verstok was right. The shrine was too easy of a target for the Burning Legion to attack. Still, he's gone and the Fangs are with him.\n\nWe're going to have to track him down for you to recover the Fangs. I should come with you but I have to stay with my people should we be attacked again.\n\nHere, my companion Ebonfang has a sense of smell like no other. He will be able to guide you to wherever Verstok is hiding. Also take this shell, through it we can communicate.\n\nMay Elune guide you.", progress = "How goes your search?", completion = "I've heard from Delandros about how you rescued the Ashen and protected the shrine.\n\nWe all owe you a great deal for your heroism, {name}. And it seems that you were able to recover the Fangs as well!\n\nI suspect this war is far from over.", objectives = "Mount upon Ebonfang and search for the Fangs of Ashamane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42431] = { id = 42431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Nithogg" }
quests[42432] = { id = 42432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: The Emerald Nightmare", description = "The Lord of Nightmare, Xavius, is still out there. Cenarius is still in grave danger, deep within the Rift of Aln.\n\nSummon your greatest allies, {name}. If we are to stare into the face of the Nightmare, we had best be ready.\n\nOnce you are ready, enter the Emerald Nightmare and defeat all the horrors you find there.", progress = "Never has the Nightmare spilled into our world. It is our duty to find the root of this evil, and destroy it.", completion = "Finally, we are triumphant, {name}! With Xavius's defeat, the Nightmare's presence will slowly recede from the Emerald Dream.\n\nThe tranquil realm of the sleepers is safe once again. Our druids will work on its restoration and recovery.\n\nThank you, Archdruid {name}. Azeroth will see many more serene days and tranquil nights because of you.", objectives = "Enter the Emerald Nightmare raid on any difficulty and defeat Lord Xavius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42433] = { id = 42433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Magic", description = "Since the Broken Isles is the epicenter of ancient night elven learning, there must be countless magical artifacts secreted away in forgotten vaults and reliquaries. We must secure them so they do not fall into the wrong hands!\n\nPerhaps you should send a champion in search of them.", progress = "What have you discovered?", completion = "Your champion has discovered some very powerful artifacts, {name}!", objectives = "Interact with your Scouting Map and complete the mission, \"Ancient Magic.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42434] = { id = 42434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Covert Operation", description = "Your champion discovered some sort of powerful magic emanating from the secretive Empyrean Society enclave in Azsuna. \n\nArchmage Vargoth asked me to request Meryl's aid in investigating it, but as you can see, Meryl is clearly too ill to travel at the moment. Would you be willing to go in his place?\n\nYou will need to prove yourself in order to gain entrance. We should be able to find something sufficient in the Hatecoil Warcamp in Azsuna.", completion = "Good; you found me, {name}.", objectives = "Meet Ravandwyr in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42435] = { id = 42435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare To Be Assimilated", description = "The Empyrean Society is a dangerous cult. They claim to study all magic regardless of its source, but in reality they focus mostly on the forbidden. They will welcome you to their enclave if you bring them a magical artifact.\n\nThe Hatecoil naga have found the perfect gifts - a Pearl of Arcane Wisdom and scrolls from the depths beneath the Nar'thalas Academy. You will have to convince them to part with a few.\n\nI will meet you on the road just north of the Empyrean Enclave.", progress = "Have you found the Pearl and scrolls?", completion = "Good. Now we should be able to enter the Empyrean Society enclave and have a look around.", objectives = "Obtain the Pearl of Arcane Wisdom and 5 Nar'thalas Scrolls and meet up with Ravandwyr north of the Empyrean Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42436] = { id = 42436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Our Allies", description = "Our Skyhorn allies could use some assistance. \n\nTheir ongoing war with the invading harpies has left them low on supplies. \n\nAnything we can give them will surely help with their efforts to rid those witches from their village.", completion = "Our alliance with the Skyhorn is stronger than ever, thanks to your efforts.", objectives = "Deliver supplies to Meliah Grayfeather.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42437] = { id = 42437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Starbuck" }
quests[42438] = { id = 42438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Renewal", description = "The Fangs of Ashamane are in danger, {name}. For ten thousand years a powerful magic ward has protected them from any would-be thieves, but the ward has weakened over time and is in danger of failing. My three most trusted Ashen have the Tel'andu seeds we need to perform the ritual of renewal,  but the woods are now crawling with demons and I fear they have fallen.\n\nNo matter what, we cannot allow the Legion to obtain the Fangs! Go and find the Tel'andu seeds, we must hurry before the ward can be broken!", progress = "Have the Tel'andu seeds?", completion = "Thank you, {name}.\n\nMy heart weeps for those who we've lost this day. The Legion will pay for this, I swear it!", objectives = "Delandros Shimmermoon wants you to search the forests of Mistvale and obtain three Tel'andu Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42439] = { id = 42439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid for the Ashen", description = "Turn your eyes above and you will see the cause of our misfortune. Ever since that ship appeared the attacks have been relentless. Many of the Ashen have been captured and even now I can hear their screams of torture.\n\nPlease, go out there and rescue as many of my followers as you can. They do not deserve the fate that awaits them if left in the Legion's grip.", completion = "<Delandros nods.>\n\nThank you, hero. Now that my people are safe we might be able to turn the tide of this battle.", objectives = "Defeat 4 Eredar Soul Lashers and free their captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42440] = { id = 42440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine in Peril", description = "You've helped us greatly, champion. Now, it is time that you tell me what brings you here.\n\n<You mention to Delandros that Archdruid Greathoof sent you to seek the Fangs of Ashamane.>\n\nHrm... if you had told me this at the outset, I would have told you to take a walk. The Fangs are our greatest treasure, but you've done a great deed for the Ashen today and I am an elf of my word.\n\nVery well, let's clear out the rest of these demons and you shall have your weapons.", progress = "Did you check on that disturbance?", completion = "What? Verstok fled with the Fangs? That fool, he's going to get himself killed!", objectives = "Assist Delandros by removing the last of the attackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42442] = { id = 42442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Night: Amalia" }
quests[42443] = { id = 42443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arluin Wants In (Tracking Quest)" }
quests[42444] = { id = 42444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plight of the Blackfeather", description = "<The ravenbear frantically gestures and points down the path. \n\nIt seems he wants you to follow him.>", completion = "Caw?\n\n<The ravenbear chieftain seems preoccupied with the gathering of reagents for some sort of ritual. Perhaps you could help him?>", objectives = "Follow the frightened ravenbear to the Blackfeather chieftain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42445] = { id = 42445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nithogg's Tribute", description = "It looks like the ravenbears have started gathering materials for some sort of tribute, but the storm drakes are keeping them from finishing what they started.  \n\nFrom the looks of it, they're gathering fully intact stag horns and long tail feathers from the greatstags and eagles nearby. \n\nIt shouldn't take too long to gather the rest of what they need.", progress = "Ca-caw?", completion = "Caw! Caw! \n\n<The ravenbear chieftain flaps his wings excitedly when he sees the reagents you've brought.>", objectives = "Collect 8 Intact Greatstag Antlers and 16 Pristine Eagle Tailfeathers in the Stormtorn Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42446] = { id = 42446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singed Feathers", description = "Ca-caw! Caw caw!\n\n<The chieftain flaps his wings and points outside where the storm dragons attack the ravenbears of his tribe. \n\nIt's plain to see that he's seeking your help to save his flock.>", completion = "The Blackfeather chieftain bows respectfully to you. \n\nYou have helped ensure the survival of his tribe.", objectives = "Kill 8 Rampaging Squallhunters in the Stormtorn Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42447] = { id = 42447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dances With Ravenbears", description = "<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.>\n\nCaw! Caw ca-caw!\n\n<It looks like he wants you to follow.>", completion = "It seems that Nithogg wasn't interested in the ravenbears' tribute.\n\nIt's probably a good idea to get out of here before he comes back...", objectives = "Help the Blackfeather ravenbears perform their tribute ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42448] = { id = 42448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Destiny", description = "The greatest heroes on Azeroth have gathered together to face the Burning Legion. But heroes alone cannot save this world.\n\nThe salvation of Azeroth will come at a price the living cannot pay. Only upon the shoulders of the dead and damned, will the world of the living be spared.\n\nYou shall be their pariah, {name}. Find the Grimoire of Damnation and do what must be done.", objectives = "Locate the Grimoire of Damnation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42449] = { id = 42449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Four Horsemen", description = "The voice of the Lich King has spoken, Deathlord, and the Knights of the Ebon Blade will obey your command.\n\nThe Four Horsemen were no ordinary death knights, they were born of pure, unholy power gifted from the Lich King to Kel'thuzad.\n\nThis unholy power to raise the dead has now been passed to you, Deathlord. I am sure you will wield it with great conviction.\n\nThe Four Horsemen will be powerful allies against the Burning Legion... and Nazgrim is a worthy choice as the firstborn.", completion = "The world of the living will forever revile us for the dark task that we begin this day...", objectives = "Speak with Thassarian in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42450] = { id = 42450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brawlgoth" }
quests[42451] = { id = 42451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalec's Plan", description = "Your champion was unable to penetrate very far inside the Arcway Vaults due to the heavy legion presence around it.  Hopefully you will have better luck following Archmage Vargoth inside.\n\nKalecgos will be waiting for you on the ridge overlooking Felsoul Hold.", completion = "Good to see you again, {name}.", objectives = "Meet Kalecgos on the ridge near the Arcway Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42452] = { id = 42452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Ebonchill", description = "Ebonchill bears a lineage of powerful wielders dating back to its maker, Alodi. He passed it on to his favorite apprentice and so on until... the archmage Arrexis, I believe.\n\nArrexis disappeared sometime around the First War. I know nothing of his fate, but the answer may well be somewhere in this library.\n\nStart by looking around here. Whatever you find should lead us to Ebonchill.", progress = "Have we found what we need yet?", completion = "From the texts you found, it is clear that Ebonchill is in the hands of Balaadur. There is no way he would not claim such a powerful staff.\n\nThat is a problem, but not an impossible one. All we need to do is get access to Balaadur.", objectives = "Investigate the forgotten stacks in the Hall of the Guardian for clues to Ebonchill's last known master, Arrexis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42453] = { id = 42453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 103 - Medium (RKS)" }
quests[42454] = { id = 42454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Khaz'goroth", description = "<Now that you have defeated Dargrul the Underking and have the Hammer of Khaz'goroth in hand, it is time to place it in Aegwynn's Gallery in the lower chambers of Dalaran.>", completion = "<Archmage Khadgar has set aside a space here for the Hammer of Khaz'goroth, as well as the rest of the Pillars of Creation.>", objectives = "Use the central teleporter in Dalaran and then place the Hammer of Khaz'goroth in Aegwynn's Gallery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42455] = { id = 42455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alodi's Gems", description = "Arrexis had a cadre of apprentices and subordinates to help him with the ritual, something you are currently lacking.\n\nIn older times, when magic was less understood and spells required vast amounts of mana to cast, we stored mana in gems for use in complex spells.\n\nLucky for us, I still have a few powerful Mana Gems in my vault, along with some other useful items. You merely need to go to the Bank of Dalaran and gain access.", progress = "You found everything in my vault? I hope the defenses weren't a bother.", completion = "Excellent! Honestly, I'm surprised you mages no longer use Mana Gems. I found them terribly useful.\n\nAt any rate, these will make up for the lack of additional mages.", objectives = "Gain access to Alodi's personal bank vault in Dalaran and retrieve the Mana Gems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42456] = { id = 42456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assn Rogue - Flavor Event 01 (Horde)" }
