quests[42566] = { id = 42566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blaze of Starlight", description = "I will deliver the good news of my recently-rediscovered vitality to my brood. You, on the other hand, have a Tidestone to deliver.", objectives = "Bring the Tidestone of Golganneth to Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42567] = { id = 42567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed to Wither", description = "So Cedonu said he saw nightfallen going into Leyhollow?\n\nI don't like the sound of that.\n\nGrandfather seems to be holding his own, but the archmage and I will keep an eye on him. You go investigate our caves.", completion = "{name}? Is that you, my friend?", objectives = "Find the nightfallen that entered Leyhollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42568] = { id = 42568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparation", description = "<With Althea's escape there is only one place to go: Stormwind.>\n\n<If Garona is keeping a similar pace on the cult's trail, she's bound to be making preparations to enter the city herself.>\n\n<Finding her is paramount before moving into the city.>", completion = "If you're with me, drench your blades with poison now. This is going to get bloody.", objectives = "Find Garona Halforcen outside Stormwind.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
