quests[42583] = { id = 42583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", description = "The Legion's defeat cannot be accomplished alone.\n\nTo win this war, we must work together, just as we did in ancient times.\n\nTo begin, we must recruit more druids to our aid. Speak to the troll Zen'tabra and the night elf Naralex.\n\nBoth of them are accomplished druids. They will gladly defend the Dreamgrove.", completion = "Good. I know Zen'tabra and Naralex, and they will serve the Dreamgrove bravely.", objectives = "Recruit Zen'tabra and Naralex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42584] = { id = 42584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sister Lilith", description = "We will need more allies on our side before we can be effective, Archdruid. A skilled dryad by the name of Sister Lilith is on her way to the Dreamgrove, but we've received word that she may be in trouble.\n\nSend Zen'tabra to her aid.", progress = "Do not delay. Sister Lilith is in trouble.", completion = "Excellent, {name}. Zen'tabra has done well.", objectives = "Use the Scouting Map and complete the mission \"Sister Lilith\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
